&lt;!-- DEBUG-VIEW START 1 APPPATH\Views\products\details.php --&gt;
&lt;style&gt;
/* Ajobmart product details — modern marketplace styling */
.aj-product-details-page {
    --aj-market-orange: #ff6a00;
    --aj-market-orange-dark: #e85f00;
    --aj-market-ink: #202a35;
    --aj-market-muted: #626d78;
    --aj-market-border: #e3e8ed;
    --aj-market-surface: #ffffff;
    --aj-market-soft: #f6f8fa;
    max-width: 1440px;
    color: var(--aj-market-ink);
    font-size: 14px;
}

.aj-product-details-page a {
    color: #176b9a;
    text-decoration: none;
}

.aj-product-details-page a:hover {
    color: var(--aj-market-orange-dark);
    text-decoration: underline;
}

.aj-product-details-page .breadcrumb {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px;
    margin-bottom: 18px !important;
    padding: 10px 0 14px;
    border-bottom: 1px solid var(--aj-market-border);
    background: transparent;
    font-size: 12px;
}

.aj-product-details-page .breadcrumb-item,
.aj-product-details-page .breadcrumb-item.active {
    color: var(--aj-market-muted);
}

.aj-product-details-page .breadcrumb-item + .breadcrumb-item::before {
    color: #a0a9b2;
}

.aj-details-gallery,
.aj-details-heading,
.aj-details-price-block,
.aj-details-shipping,
.aj-details-section {
    min-width: 0;
    background: var(--aj-market-surface);
}

.aj-details-gallery {
    position: sticky;
    top: 18px;
    width: 100%;
}

.aj-details-main-image {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: clamp(340px, 39vw, 500px);
    min-height: 0;
    padding: 22px;
    overflow: hidden;
    box-sizing: border-box;
    background: linear-gradient(180deg, #fff 0%, #fbfcfd 100%);
    border: 1px solid var(--aj-market-border);
    border-radius: 12px;
}

.aj-details-main-image &gt; img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    cursor: zoom-in;
    transition: transform .25s ease;
}

.aj-details-main-image:hover &gt; img {
    transform: scale(1.015);
}

.aj-details-no-image {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    width: 100%;
    min-height: 260px;
    color: #8a949e;
    font-size: 13px;
}

.aj-details-no-image i {
    font-size: 48px;
    color: #b7c0c8;
}

.aj-image-zoom-btn {
    position: absolute;
    right: 14px;
    bottom: 14px;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    padding: 0;
    border: 1px solid #d9e0e6;
    border-radius: 50%;
    background: rgba(255,255,255,.96);
    color: #25313c;
    font-size: 19px;
    box-shadow: 0 3px 12px rgba(25, 38, 50, .08);
    cursor: pointer;
    transition: background .2s ease, color .2s ease, transform .2s ease;
}

.aj-image-zoom-btn:hover {
    color: var(--aj-market-orange-dark);
    background: #fff7f1;
    transform: translateY(-1px);
}

.aj-details-thumbnails {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
    margin-top: 13px;
}

.aj-details-thumbnail {
    flex: 0 0 68px;
    width: 68px;
    height: 68px;
    padding: 4px;
    overflow: hidden;
    border: 1px solid #d8dfe5;
    border-radius: 9px;
    background: #fff;
    cursor: pointer;
    transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.aj-details-thumbnail img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    pointer-events: none;
}

.aj-details-thumbnail.active,
.aj-details-thumbnail:hover {
    border: 2px solid var(--aj-market-orange);
    padding: 3px;
    background: #fffaf6;
    box-shadow: 0 0 0 2px rgba(255, 106, 0, .08);
}

.aj-details-heading {
    padding: 2px 0 16px;
    border-bottom: 1px solid var(--aj-market-border);
}

.aj-details-brand {
    margin-bottom: 8px;
    color: #176b9a;
    font-size: 13px;
    font-weight: 650;
    letter-spacing: .01em;
}

.aj-details-heading h1 {
    margin: 0 0 12px;
    color: #202a35;
    font-size: clamp(22px, 2.1vw, 30px);
    font-weight: 600;
    line-height: 1.32;
    letter-spacing: -.025em;
    overflow-wrap: anywhere;
}

.aj-details-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 7px 10px;
    color: var(--aj-market-muted);
    font-size: 12px;
}

.aj-details-meta span {
    display: inline-flex;
    align-items: center;
    padding: 5px 9px;
    border: 1px solid #e6ebef;
    border-radius: 5px;
    background: #f8fafb;
}

.aj-details-price-block {
    margin-top: 0;
    padding: 20px 0 18px;
    border-bottom: 1px solid var(--aj-market-border);
}

.aj-details-price {
    display: inline-block;
    color: #202a35;
    font-size: clamp(28px, 2.7vw, 36px);
    font-weight: 750;
    line-height: 1.2;
    letter-spacing: -.035em;
    font-variant-numeric: tabular-nums;
}

.aj-details-mrp {
    margin-left: 9px;
    color: #78828c;
    font-size: 15px;
}

.aj-details-discount {
    display: inline-block;
    margin-left: 8px;
    padding: 5px 8px;
    border-radius: 5px;
    background: #fff0e6;
    color: #c84f00;
    font-size: 12px;
    font-weight: 750;
    vertical-align: 4px;
}

.aj-details-tax-note {
    margin-top: 7px;
    color: var(--aj-market-muted);
    font-size: 12px;
    line-height: 1.5;
}

.aj-details-availability {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    padding: 17px 0;
    border-bottom: 1px solid var(--aj-market-border);
}

.aj-details-availability &gt; div {
    display: flex;
    flex: 1 1 105px;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
    padding: 11px 12px;
    border: 1px solid #e8edf1;
    border-radius: 8px;
    background: #fafbfc;
}

.aj-details-label {
    color: #697580;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .035em;
    text-transform: uppercase;
}

.aj-details-availability strong,
.aj-details-availability &gt; div &gt; span:not(.aj-details-label) {
    color: #293642;
    font-size: 13px;
    font-weight: 700;
}

.aj-stock-available {
    color: #168447 !important;
}

.aj-stock-unavailable {
    color: #c62828 !important;
}

.aj-product-details-page .aj-product-cart-action {
    margin-top: 18px;
}

.aj-product-details-page .aj-add-cart {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    width: 100%;
    min-height: 49px;
    max-width: 100%;
    padding: 12px 20px;
    border: 1px solid #f0a33a;
    border-radius: 999px;
    background: linear-gradient(180deg, #ffd978 0%, #ffc342 100%);
    color: #202a35;
    font-size: 15px;
    font-weight: 750;
    box-shadow: 0 2px 0 rgba(148, 89, 0, .09);
    transition: filter .2s ease, transform .2s ease, box-shadow .2s ease;
}

.aj-product-details-page .aj-add-cart:hover:not(:disabled) {
    filter: brightness(.98);
    box-shadow: 0 4px 12px rgba(156, 105, 0, .14);
    transform: translateY(-1px);
}

.aj-product-details-page .aj-add-cart:focus-visible,
.aj-product-details-page .aj-details-thumbnail:focus-visible,
.aj-product-details-page .aj-image-zoom-btn:focus-visible {
    outline: 3px solid rgba(255, 106, 0, .28);
    outline-offset: 2px;
}

.aj-product-details-page .aj-add-cart:disabled {
    border-color: #d8dde2;
    background: #e9edf0;
    color: #79838c;
    cursor: not-allowed;
    box-shadow: none;
}

.aj-details-shipping {
    margin-top: 18px;
    padding: 17px 18px;
    border: 1px solid var(--aj-market-border);
    border-radius: 10px;
    background: #fff;
}

.aj-details-shipping h5 {
    display: flex;
    align-items: center;
    gap: 9px;
    margin: 0 0 12px;
    color: #25313c;
    font-size: 15px;
    font-weight: 750;
}

.aj-details-shipping h5 i {
    color: #176b9a;
    font-size: 18px;
}

.aj-details-shipping &gt; div {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    padding: 10px 0;
    border-top: 1px solid #edf0f2;
    font-size: 12px;
}

.aj-details-shipping &gt; div span {
    color: #68737e;
}

.aj-details-shipping &gt; div strong {
    color: #303c47;
    text-align: right;
    font-weight: 650;
}

.aj-details-section {
    margin-top: 24px;
    padding: 24px;
    border: 1px solid var(--aj-market-border);
    border-radius: 12px;
    box-shadow: 0 2px 10px rgba(22, 34, 46, .025);
}

.aj-details-section h2 {
    margin: 0 0 18px;
    padding-bottom: 13px;
    border-bottom: 1px solid #e9edf1;
    color: #25313c;
    font-size: 20px;
    font-weight: 700;
    letter-spacing: -.015em;
}

.aj-details-description {
    color: #45515c;
    font-size: 14px;
    line-height: 1.85;
    overflow-wrap: anywhere;
}

.aj-details-features {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px 20px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.aj-details-features li {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    color: #45515c;
    line-height: 1.6;
}

.aj-details-features i {
    flex: 0 0 auto;
    margin-top: 2px;
    color: #168447;
    font-size: 17px;
}

.aj-details-spec-table {
    margin: 0;
    color: #34414d;
    font-size: 13px;
    --bs-table-bg: transparent;
}

.aj-details-spec-table th,
.aj-details-spec-table td {
    width: 50%;
    padding: 12px 14px;
    border-color: #e8edf1;
    vertical-align: middle;
    overflow-wrap: anywhere;
}

.aj-details-spec-table th {
    background: #f7f9fa;
    color: #53606c;
    font-weight: 650;
}

.aj-details-spec-table tr:nth-child(even) td {
    background: #fcfdfd;
}

.aj-product-details-page &gt; .mt-4 .btn {
    padding: 10px 16px;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 650;
}

/* Full-screen image zoom; functionality retained */
.aj-image-zoom-modal {
    position: fixed;
    inset: 0;
    z-index: 99999;
    display: none;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: rgba(14, 20, 26, .96);
}

.aj-image-zoom-modal.open {
    display: flex;
}

#ajZoomPreviewImage {
    display: block;
    max-width: 85vw;
    max-height: 82vh;
    object-fit: contain;
    transform-origin: center center;
    cursor: grab;
    user-select: none;
    -webkit-user-drag: none;
    touch-action: none;
}

#ajZoomPreviewImage:active {
    cursor: grabbing;
}

.aj-zoom-close,
.aj-zoom-control {
    position: absolute;
    z-index: 3;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    padding: 0;
    border: 1px solid rgba(255,255,255,.2);
    border-radius: 50%;
    background: #fff;
    color: #202a35;
    font-size: 19px;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0,0,0,.18);
}

.aj-zoom-close {
    top: 20px;
    right: 20px;
}

.aj-zoom-plus {
    right: 22px;
    bottom: 70px;
}

.aj-zoom-minus {
    right: 22px;
    bottom: 18px;
}

.aj-zoom-hint {
    position: absolute;
    bottom: 20px;
    left: 20px;
    max-width: 65%;
    color: #fff;
    font-size: 12px;
    opacity: .82;
    pointer-events: none;
}

@media (max-width: 991.98px) {
    .aj-details-gallery {
        position: static;
    }

    .aj-details-main-image {
        height: 390px;
    }
}

@media (max-width: 767.98px) {
    .aj-product-details-page {
        padding-right: 14px;
        padding-left: 14px;
    }

    .aj-product-details-page .breadcrumb {
        margin-bottom: 14px !important;
        padding: 6px 0 12px;
    }

    .aj-details-main-image {
        height: min(86vw, 360px);
        padding: 15px;
        border-radius: 10px;
    }

    .aj-details-thumbnails {
        gap: 8px;
        margin-top: 10px;
    }

    .aj-details-thumbnail {
        flex-basis: 60px;
        width: 60px;
        height: 60px;
    }

    .aj-details-heading h1 {
        font-size: 23px;
    }

    .aj-details-price-block {
        padding: 17px 0;
    }

    .aj-details-price {
        font-size: 30px;
    }

    .aj-details-availability {
        gap: 8px;
    }

    .aj-details-availability &gt; div {
        flex-basis: calc(50% - 8px);
        padding: 10px;
    }

    .aj-details-section {
        margin-top: 18px;
        padding: 18px 15px;
        border-radius: 10px;
    }

    .aj-details-section h2 {
        font-size: 18px;
    }

    .aj-details-features {
        grid-template-columns: minmax(0, 1fr);
        gap: 10px;
    }

    .aj-details-spec-table th,
    .aj-details-spec-table td {
        padding: 10px 9px;
        font-size: 12px;
    }

    #ajZoomPreviewImage {
        max-width: 96vw;
        max-height: 78vh;
    }

    .aj-zoom-close {
        top: 12px;
        right: 12px;
    }

    .aj-zoom-plus,
    .aj-zoom-minus {
        right: 12px;
    }

    .aj-zoom-hint {
        bottom: 14px;
        left: 12px;
        max-width: 72%;
    }
}

@media (prefers-reduced-motion: reduce) {
    .aj-product-details-page *,
    .aj-product-details-page *::before,
    .aj-product-details-page *::after {
        scroll-behavior: auto !important;
        transition-duration: .01ms !important;
        animation-duration: .01ms !important;
        animation-iteration-count: 1 !important;
    }
}


/* Ajobmart product details accordion */
.aj-details-accordion {
    margin-top: 22px;
    border: 1px solid var(--aj-market-border);
    border-radius: 12px;
    overflow: hidden;
    background: #fff;
}

.aj-details-accordion-item {
    border-bottom: 1px solid var(--aj-market-border);
}

.aj-details-accordion-item:last-child {
    border-bottom: 0;
}

.aj-details-accordion-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    width: 100%;
    min-height: 62px;
    padding: 17px 20px;
    border: 0;
    background: #fff;
    color: var(--aj-market-ink);
    text-align: left;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    transition: background .2s ease;
}

.aj-details-accordion-header:hover {
    background: #fffaf6;
}

.aj-details-accordion-header:focus-visible {
    outline: 3px solid rgba(255, 106, 0, .3);
    outline-offset: -3px;
}

.aj-details-accordion-title {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.aj-details-accordion-title &gt; i {
    flex: 0 0 auto;
    color: var(--aj-market-orange-dark);
    font-size: 19px;
}

.aj-details-accordion-arrow {
    flex: 0 0 auto;
    color: #68737e;
    font-size: 15px;
    transition: transform .25s ease;
}

.aj-details-accordion-header[aria-expanded=&quot;true&quot;]
.aj-details-accordion-arrow {
    transform: rotate(180deg);
}

.aj-details-accordion-panel {
    padding: 0 20px 22px;
}

.aj-details-accordion-panel[hidden] {
    display: none !important;
}

/* Remove old section spacing when sections are inside accordion */
.aj-details-accordion .aj-details-section {
    margin: 0;
    padding: 8px 0 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
}

.aj-details-accordion .aj-details-section h2 {
    display: none;
}

@media (max-width: 767.98px) {
    .aj-details-accordion {
        margin-top: 18px;
        border-radius: 10px;
    }

    .aj-details-accordion-header {
        min-height: 56px;
        padding: 15px 13px;
        font-size: 14px;
    }

    .aj-details-accordion-title {
        gap: 9px;
    }

    .aj-details-accordion-panel {
        padding: 0 13px 18px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .aj-details-accordion-arrow {
        transition: none;
    }
}



/* Ajobmart product reviews */
.aj-product-reviews {
    margin-top: 22px;
}

.aj-review-summary {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 25px;
    padding: 20px;
    border: 1px solid var(--aj-market-border);
    border-radius: 10px;
    background: #fff;
}

.aj-review-average {
    min-width: 130px;
    text-align: center;
}

.aj-review-average strong {
    display: block;
    color: #202a35;
    font-size: 42px;
    line-height: 1.2;
}

.aj-review-stars {
    color: #f5a623;
    font-size: 17px;
    letter-spacing: 2px;
}

.aj-review-average small {
    display: block;
    margin-top: 5px;
    color: #697580;
    font-size: 12px;
}

.aj-review-breakdown {
    flex: 1;
    min-width: 180px;
}

.aj-review-rating-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 7px 0;
    font-size: 12px;
    color: #596570;
}

.aj-review-rating-row span:first-child {
    width: 38px;
}

.aj-review-progress {
    flex: 1;
    height: 7px;
    overflow: hidden;
    border-radius: 10px;
    background: #edf0f2;
}

.aj-review-progress span {
    display: block;
    height: 100%;
    border-radius: 10px;
    background: #f5a623;
}

.aj-review-count {
    color: #78828c;
    font-size: 12px;
}

.aj-review-card {
    padding: 18px 0;
    border-bottom: 1px solid #e9edf1;
}

.aj-review-card:last-child {
    border-bottom: 0;
}

.aj-review-user {
    display: flex;
    align-items: center;
    gap: 11px;
}

.aj-review-avatar {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    flex-shrink: 0;
    border-radius: 50%;
    background: #fff0e6;
    color: #e85f00;
    font-size: 15px;
    font-weight: 700;
}

.aj-review-user-info strong {
    display: block;
    color: #293642;
    font-size: 13px;
}

.aj-review-user-info small {
    color: #89939c;
    font-size: 11px;
}

.aj-review-card .aj-review-stars {
    margin-top: 9px;
    font-size: 14px;
}

.aj-review-card h6 {
    margin: 8px 0 5px;
    color: #303c47;
    font-size: 14px;
    font-weight: 700;
}

.aj-review-card p {
    margin: 0;
    color: #596570;
    font-size: 13px;
    line-height: 1.7;
}

.aj-review-demo-notice {
    margin-bottom: 14px;
    padding: 9px 12px;
    border-radius: 6px;
    background: #fff8e8;
    color: #856404;
    font-size: 12px;
}

@media (max-width: 575px) {
    .aj-review-summary {
        gap: 15px;
        padding: 14px;
    }

    .aj-review-average {
        min-width: 90px;
    }

    .aj-review-average strong {
        font-size: 34px;
    }
}


/* WOW Offer Card */
.aj-wow-offer {
    margin: 18px 0;
    border: 1px solid #f3d28b;
    border-radius: 13px;
    background: linear-gradient(135deg, #fffdf5, #fff7e6);
    box-shadow: 0 5px 18px rgba(0, 0, 0, 0.10);
    overflow: hidden;
}

.aj-wow-offer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 13px 16px;
    cursor: pointer;
    gap: 12px;
}

.aj-wow-offer-heading {
    display: flex;
    align-items: center;
    gap: 11px;
}

.aj-wow-icon {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: #fff0c2;
    color: #d58b00;
    font-size: 20px;
}

.aj-wow-offer-heading strong {
    display: block;
    color: #b66c00;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: .5px;
}

.aj-wow-offer-heading small {
    display: block;
    color: #777;
    font-size: 12px;
    margin-top: 2px;
}

.aj-wow-arrow {
    color: #b66c00;
    font-size: 15px;
    transition: transform .25s ease;
}

.aj-wow-offer.is-open .aj-wow-arrow {
    transform: rotate(180deg);
}

.aj-wow-offer-content {
    padding: 0 16px 15px;
    border-top: 1px dashed #e9cf98;
}

.aj-wow-offer-details {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 14px 0;
}

.aj-wow-discount {
    min-width: 105px;
    padding: 10px;
    text-align: center;
    border-radius: 10px;
    background: #fff0c2;
}

.aj-wow-discount strong {
    display: block;
    color: #c07800;
    font-size: 21px;
    font-weight: 800;
}

.aj-wow-discount span {
    display: block;
    color: #74500c;
    font-size: 11px;
    font-weight: 600;
}

.aj-wow-offer-details p {
    margin: 0;
    color: #555;
    font-size: 13px;
    line-height: 1.5;
}

.aj-wow-apply-btn {
    width: 100%;
    padding: 10px 15px;
    border: 0;
    border-radius: 8px;
    background: #e89b16;
    color: #fff;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    transition: background .2s ease;
}

.aj-wow-apply-btn:hover {
    background: #c98208;
}

.aj-wow-applied-message {
    margin-top: 10px;
    color: #168348;
    font-size: 13px;
    font-weight: 600;
    text-align: center;
}

.aj-wow-applied-message i {
    margin-right: 5px;
}

@media (max-width: 576px) {
    .aj-wow-offer-details {
        align-items: flex-start;
    }
}

.aj-wow-header-right {
    display: flex;
    align-items: center;
    gap: 12px;
}

.aj-wow-header-price {
    text-align: right;
    white-space: nowrap;
}

.aj-wow-header-price strong {
    display: block;
    color: #168348;
    font-size: 19px;
    font-weight: 800;
}

.aj-wow-header-price del {
    display: block;
    color: #888;
    font-size: 11px;
}

.aj-wow-arrow {
    flex-shrink: 0;
}

@media (max-width: 420px) {
    .aj-wow-offer-header {
        padding: 11px;
    }

    .aj-wow-header-right {
        gap: 7px;
    }

    .aj-wow-header-price strong {
        font-size: 16px;
    }

    .aj-wow-offer-heading strong {
        font-size: 13px;
    }

    .aj-wow-offer-heading small {
        font-size: 10px;
    }
}

/* Product details cart buttons */
.aj-product-cart-action {
    align-items: center;
}

.aj-product-cart-action .aj-add-cart,
.aj-product-cart-action .aj-go-to-cart {
    width: 100%;
    min-height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    border: none;
    border-radius: 9px;
    background: #f39c12;
    color: #fff;
    font-weight: 700;
    font-size: 15px;
    text-decoration: none;
    cursor: pointer;
}

.aj-product-cart-action .aj-add-cart:disabled {
    background: #999;
    cursor: not-allowed;
}

.aj-product-cart-action .aj-go-to-cart {
    background: #198754;
}


@media (max-width: 767.98px) {

    #ajProductCartAction.aj-mobile-floating {
        position: fixed !important;
        left: 0 !important;
        right: 0 !important;
        bottom: 40px !important;
        width: 100% !important;
        z-index: 999999 !important;
        background: #fff !important;
        padding: 12px 15px !important;
        box-shadow: 0 -3px 12px rgba(0, 0, 0, 0.15);
    }

}


